let lang='en';
function get(k){return (D[lang]&&D[lang][k])||null}
function preserveHeadline(el,value){if(value.includes('|')&&el.querySelector('em')){const i=value.indexOf('|');el.replaceChildren(document.createTextNode(value.slice(0,i)),document.createElement('br'));const em=document.createElement('em');em.textContent=value.slice(i+1);el.appendChild(em)}else{el.textContent=value}}
function setLanguage(code,showNotice=true){lang=(code==='en'||D[code])?code:'en';try{localStorage.setItem('et_lang',lang)}catch(e){};document.documentElement.lang=lang;
 document.querySelectorAll('[data-i18n]').forEach(el=>{if(!el.dataset.originalHtml)el.dataset.originalHtml=el.innerHTML;const key=el.dataset.i18n;const val=get(key);if(!val){if(lang==='en')el.innerHTML=el.dataset.originalHtml;return;}if(el.querySelector('em')&&val.includes('|'))preserveHeadline(el,val);else el.textContent=val});
 document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{if(!el.dataset.originalPlaceholder)el.dataset.originalPlaceholder=el.placeholder;el.placeholder=get(el.dataset.i18nPlaceholder)||el.dataset.originalPlaceholder});
 const dialog=document.querySelector('#translationDialog'),target=document.querySelector('#translationDialogText');if(dialog && showNotice && lang!=='en'){if(target)target.textContent=N[lang]||'';dialog.hidden=false;document.body.classList.add('translation-modal-open');document.querySelector('#translationDialogAcknowledge')?.focus()}else if(dialog){dialog.hidden=true;document.body.classList.remove('translation-modal-open')}
 const short=document.querySelector('#languageShort');if(short)short.textContent=lang.toUpperCase();document.querySelectorAll('#languageMenu button').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));document.dispatchEvent(new CustomEvent('exims:langchange',{detail:{language:lang}}))}
function load(){try{lang=localStorage.getItem('et_lang')||'en'}catch(e){};setLanguage(lang,false)}
window.EXIMS_T={setLanguage,get,language:()=>lang};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',load);else load();
